from typing import Dict
EMBEDDED_TEMPLATES: Dict[str, str] = {'base.html': '<!DOCTYPE html>\n<html lang="en">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>RBAC Simulator</title>\n    <!-- Tailwind CSS CDN -->\n    <script src="https://cdn.tailwindcss.com"></script>\n    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">\n    <link rel="stylesheet" href="{{ url_for(\'static\', filename=\'style.css\') }}">\n</head>\n<body class="bg-slate-50 text-slate-800 min-h-screen flex flex-col font-sans antialiased">\n\n    <!-- Professional Clean Header -->\n    <header class="bg-white border-b border-slate-200 sticky top-0 z-50 shadow-xs">\n        <div class="max-w-6xl mx-auto px-4 sm:px-6 h-16 flex items-center justify-between">\n            <!-- Brand -->\n            <div class="flex items-center space-x-3">\n                <div class="h-9 w-9 rounded-lg bg-blue-600 flex items-center justify-center text-white shadow-sm">\n                    <i class="fa-solid fa-shield-halved text-base"></i>\n                </div>\n                <div>\n                    <h1 class="text-base font-bold text-slate-900 tracking-tight">RBAC Simulator</h1>\n                    <p class="text-[11px] text-slate-500 font-medium">Role-Based Access Control</p>\n                </div>\n            </div>\n\n            <!-- Role Switcher Control -->\n            <div class="flex items-center space-x-1.5 bg-slate-100 p-1 rounded-lg border border-slate-200">\n                <span class="text-xs text-slate-500 px-2 font-medium hidden sm:inline">Role:</span>\n                <button onclick="switchRole(\'Admin\')" id="btn-role-Admin" \n                    class="px-3 py-1.5 rounded-md text-xs font-semibold transition flex items-center space-x-1.5 {% if current_user and current_user.role.value == \'Admin\' %}bg-red-600 text-white shadow-xs{% else %}text-slate-600 hover:text-slate-900 hover:bg-white{% endif %}">\n                    <i class="fa-solid fa-user-shield text-[11px]"></i>\n                    <span>Admin</span>\n                </button>\n                <button onclick="switchRole(\'Teacher\')" id="btn-role-Teacher" \n                    class="px-3 py-1.5 rounded-md text-xs font-semibold transition flex items-center space-x-1.5 {% if current_user and current_user.role.value == \'Teacher\' %}bg-amber-600 text-white shadow-xs{% else %}text-slate-600 hover:text-slate-900 hover:bg-white{% endif %}">\n                    <i class="fa-solid fa-chalkboard-user text-[11px]"></i>\n                    <span>Teacher</span>\n                </button>\n                <button onclick="switchRole(\'Student\')" id="btn-role-Student" \n                    class="px-3 py-1.5 rounded-md text-xs font-semibold transition flex items-center space-x-1.5 {% if current_user and current_user.role.value == \'Student\' %}bg-emerald-600 text-white shadow-xs{% else %}text-slate-600 hover:text-slate-900 hover:bg-white{% endif %}">\n                    <i class="fa-solid fa-user-graduate text-[11px]"></i>\n                    <span>Student</span>\n                </button>\n            </div>\n        </div>\n    </header>\n\n    <!-- Global Floating Alerts / Toasts Container -->\n    <div id="toast-container" class="fixed top-20 right-4 z-50 flex flex-col space-y-2 pointer-events-none"></div>\n\n    <!-- Main Container -->\n    <main class="flex-grow max-w-6xl mx-auto w-full px-4 sm:px-6 py-6 space-y-6">\n        {% block content %}{% endblock %}\n    </main>\n\n    <!-- Footer -->\n    <footer class="bg-white border-t border-slate-200 py-4 text-center text-xs text-slate-500">\n        Role-Based Access Control (RBAC) Simulator &bull; Academic Records Management\n    </footer>\n\n    <!-- Client Script -->\n    <script src="{{ url_for(\'static\', filename=\'main.js\') }}"></script>\n</body>\n</html>\n', 'index.html': '{% extends "base.html" %}\n\n{% block content %}\n<div class="space-y-6">\n\n    <!-- Active User & Role Context Bar -->\n    <div class="bg-white border border-slate-200 rounded-xl p-4 flex flex-col sm:flex-row sm:items-center justify-between gap-3 shadow-xs">\n        <div class="flex items-center space-x-3.5">\n            <div class="w-10 h-10 rounded-full flex items-center justify-center font-bold text-sm\n                {% if current_user.role.value == \'Admin\' %}bg-red-50 text-red-600 border border-red-200\n                {% elif current_user.role.value == \'Teacher\' %}bg-amber-50 text-amber-700 border border-amber-200\n                {% else %}bg-emerald-50 text-emerald-700 border border-emerald-200{% endif %}">\n                {% if current_user.role.value == \'Admin\' %}<i class="fa-solid fa-crown text-sm"></i>\n                {% elif current_user.role.value == \'Teacher\' %}<i class="fa-solid fa-chalkboard-user text-sm"></i>\n                {% else %}<i class="fa-solid fa-user-graduate text-sm"></i>{% endif %}\n            </div>\n            <div>\n                <div class="text-sm font-bold text-slate-900 flex items-center gap-2">\n                    <span>{{ current_user.full_name }}</span>\n                    <span class="text-[11px] px-2 py-0.5 rounded font-semibold \n                        {% if current_user.role.value == \'Admin\' %}bg-red-50 text-red-700 border border-red-200\n                        {% elif current_user.role.value == \'Teacher\' %}bg-amber-50 text-amber-800 border border-amber-200\n                        {% else %}bg-emerald-50 text-emerald-800 border border-emerald-200{% endif %}">\n                        {{ current_user.role.value }}\n                    </span>\n                </div>\n                <div class="text-xs text-slate-500 mt-0.5">\n                    {% if current_user.role.value == \'Admin\' %}\n                        Full Administrative Access: Permitted to <strong class="text-slate-700">View, Add, Edit, and Delete</strong> records.\n                    {% elif current_user.role.value == \'Teacher\' %}\n                        Faculty Access: Permitted to <strong class="text-slate-700">View, Add, and Edit</strong>. Deletion is <span class="text-red-600 font-semibold">forbidden</span>.\n                    {% else %}\n                        Student Access: <strong class="text-slate-700">Read-Only (View)</strong>. Adding, Editing, or Deleting is <span class="text-red-600 font-semibold">forbidden</span>.\n                    {% endif %}\n                </div>\n            </div>\n        </div>\n\n        <div class="flex items-center space-x-2">\n            <button onclick="openAddRecordModal()" class="px-3.5 py-2 rounded-lg text-xs font-semibold bg-blue-600 hover:bg-blue-700 text-white flex items-center space-x-1.5 shadow-xs transition">\n                <i class="fa-solid fa-plus text-[11px]"></i>\n                <span>Add Record</span>\n            </button>\n            <button onclick="resetDatabase()" class="px-3 py-2 rounded-lg text-xs font-semibold bg-white hover:bg-slate-50 text-slate-700 border border-slate-300 flex items-center space-x-1 shadow-xs transition" title="Reset sample records">\n                <i class="fa-solid fa-arrows-rotate text-[11px]"></i>\n                <span class="hidden sm:inline">Reset</span>\n            </button>\n        </div>\n    </div>\n\n    <!-- Security Policy Feedback Box (Shows real-time Access Control decisions) -->\n    <div id="security-alert-box" class="hidden p-4 rounded-xl border text-xs transition duration-200 shadow-xs">\n        <div class="flex items-start space-x-3">\n            <div id="security-alert-icon" class="text-lg mt-0.5"></div>\n            <div class="flex-1">\n                <div id="security-alert-title" class="font-bold text-sm"></div>\n                <div id="security-alert-message" class="mt-1 leading-relaxed text-xs"></div>\n            </div>\n            <button onclick="dismissSecurityAlert()" class="text-slate-400 hover:text-slate-700"><i class="fa-solid fa-xmark text-sm"></i></button>\n        </div>\n    </div>\n\n    <!-- Section 1: Academic Records Table -->\n    <div class="bg-white border border-slate-200 rounded-xl overflow-hidden shadow-xs">\n        <div class="px-5 py-3.5 border-b border-slate-200 bg-slate-50/70 flex items-center justify-between">\n            <div class="text-sm font-bold text-slate-900 flex items-center">\n                <i class="fa-solid fa-database text-blue-600 mr-2 text-xs"></i>\n                Academic Records\n            </div>\n            <span class="text-xs text-slate-500 font-medium">{{ records|length }} records</span>\n        </div>\n\n        <div class="overflow-x-auto">\n            <table class="w-full text-left text-xs">\n                <thead>\n                    <tr class="bg-slate-50 text-slate-600 uppercase text-[11px] font-semibold border-b border-slate-200">\n                        <th class="py-3 px-4">ID</th>\n                        <th class="py-3 px-4">Student</th>\n                        <th class="py-3 px-4">Course</th>\n                        <th class="py-3 px-4 text-center">Grade</th>\n                        <th class="py-3 px-4 text-center">Attendance</th>\n                        <th class="py-3 px-4">Remarks</th>\n                        <th class="py-3 px-4 text-center">Actions</th>\n                    </tr>\n                </thead>\n                <tbody class="divide-y divide-slate-100 font-sans" id="records-tbody">\n                    {% for r in records %}\n                    <tr class="hover:bg-slate-50/80 transition" id="row-{{ r.record_id }}">\n                        <td class="py-3.5 px-4 font-mono font-semibold text-blue-600 whitespace-nowrap">{{ r.record_id }}</td>\n                        <td class="py-3.5 px-4 font-semibold text-slate-900 whitespace-nowrap">{{ r.student_name }}</td>\n                        <td class="py-3.5 px-4 text-slate-700">{{ r.course }}</td>\n                        <td class="py-3.5 px-4 text-center whitespace-nowrap">\n                            <span class="inline-block px-2.5 py-0.5 rounded font-mono font-bold text-xs\n                                {% if r.grade in [\'A+\', \'A\', \'A-\'] %}bg-emerald-50 text-emerald-700 border border-emerald-200\n                                {% elif r.grade in [\'B+\', \'B\'] %}bg-blue-50 text-blue-700 border border-blue-200\n                                {% else %}bg-amber-50 text-amber-700 border border-amber-200{% endif %}">\n                                {{ r.grade }}\n                            </span>\n                        </td>\n                        <td class="py-3.5 px-4 text-center font-mono text-slate-700 whitespace-nowrap">{{ r.attendance }}%</td>\n                        <td class="py-3.5 px-4 text-slate-500 truncate max-w-xs" title="{{ r.remarks }}">{{ r.remarks }}</td>\n                        <td class="py-3.5 px-4 text-center whitespace-nowrap">\n                            <div class="inline-flex items-center space-x-1.5">\n                                <!-- View -->\n                                <button onclick="viewRecord(\'{{ r.record_id }}\')" class="px-2.5 py-1 rounded-md bg-white hover:bg-slate-50 text-slate-700 border border-slate-300 text-xs font-medium transition shadow-2xs">\n                                    <i class="fa-solid fa-eye mr-1 text-[10px] text-blue-600"></i> View\n                                </button>\n                                <!-- Edit -->\n                                <button onclick="openEditRecordModal(\'{{ r.record_id }}\', \'{{ r.student_name }}\', \'{{ r.course }}\', \'{{ r.grade }}\', \'{{ r.attendance }}\', \'{{ r.remarks|replace("\'", "\\\\\'") }}\')" class="px-2.5 py-1 rounded-md bg-white hover:bg-slate-50 text-slate-700 border border-slate-300 text-xs font-medium transition shadow-2xs">\n                                    <i class="fa-solid fa-pen mr-1 text-[10px] text-amber-600"></i> Edit\n                                </button>\n                                <!-- Delete -->\n                                <button onclick="deleteRecord(\'{{ r.record_id }}\', \'{{ r.student_name }}\')" class="px-2.5 py-1 rounded-md bg-white hover:bg-red-50 text-red-700 border border-slate-300 hover:border-red-200 text-xs font-medium transition shadow-2xs">\n                                    <i class="fa-solid fa-trash mr-1 text-[10px] text-red-600"></i> Delete\n                                </button>\n                            </div>\n                        </td>\n                    </tr>\n                    {% endfor %}\n                </tbody>\n            </table>\n        </div>\n    </div>\n\n    <!-- Section 2: Permissions Matrix & One-Click Verification -->\n    <div class="bg-white border border-slate-200 rounded-xl p-5 shadow-xs space-y-4">\n        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3">\n            <div>\n                <h2 class="text-sm font-bold text-slate-900 flex items-center">\n                    <i class="fa-solid fa-table-cells text-slate-700 mr-2 text-xs"></i>\n                    Role Permissions Matrix\n                </h2>\n                <p class="text-xs text-slate-500 mt-0.5">\n                    Defines permitted and denied actions for each role per the Principle of Least Privilege.\n                </p>\n            </div>\n            <!-- Test & Verify Button -->\n            <button onclick="runVerification()" id="btn-verify" class="px-4 py-2 rounded-lg text-xs font-semibold bg-emerald-600 hover:bg-emerald-700 text-white flex items-center space-x-1.5 shadow-xs transition">\n                <i class="fa-solid fa-clipboard-check text-[11px]"></i>\n                <span>Verify Matrix (Test All)</span>\n            </button>\n        </div>\n\n        <!-- Matrix Table -->\n        <div class="overflow-x-auto border border-slate-200 rounded-lg">\n            <table class="w-full text-left text-xs">\n                <thead>\n                    <tr class="bg-slate-50 text-slate-600 uppercase text-[11px] font-semibold border-b border-slate-200">\n                        <th class="py-2.5 px-4">Action</th>\n                        <th class="py-2.5 px-4 text-center w-28">\n                            <span class="text-red-700 font-bold">Admin</span>\n                        </th>\n                        <th class="py-2.5 px-4 text-center w-28">\n                            <span class="text-amber-800 font-bold">Teacher</span>\n                        </th>\n                        <th class="py-2.5 px-4 text-center w-28">\n                            <span class="text-emerald-800 font-bold">Student</span>\n                        </th>\n                        <th class="py-2.5 px-4">Security Policy & Least Privilege Rule</th>\n                    </tr>\n                </thead>\n                <tbody class="divide-y divide-slate-100">\n                    <tr class="hover:bg-slate-50/60">\n                        <td class="py-2.5 px-4 font-bold text-slate-900">View Record</td>\n                        <td class="py-2.5 px-4 text-center text-emerald-700 font-bold"><i class="fa-solid fa-check mr-1"></i> ALLOW</td>\n                        <td class="py-2.5 px-4 text-center text-emerald-700 font-bold"><i class="fa-solid fa-check mr-1"></i> ALLOW</td>\n                        <td class="py-2.5 px-4 text-center text-emerald-700 font-bold"><i class="fa-solid fa-check mr-1"></i> ALLOW</td>\n                        <td class="py-2.5 px-4 text-slate-500 text-[11px]">All roles need read access to inspect grades and course progress.</td>\n                    </tr>\n                    <tr class="hover:bg-slate-50/60">\n                        <td class="py-2.5 px-4 font-bold text-slate-900">Add Record</td>\n                        <td class="py-2.5 px-4 text-center text-emerald-700 font-bold"><i class="fa-solid fa-check mr-1"></i> ALLOW</td>\n                        <td class="py-2.5 px-4 text-center text-emerald-700 font-bold"><i class="fa-solid fa-check mr-1"></i> ALLOW</td>\n                        <td class="py-2.5 px-4 text-center text-red-600 font-bold"><i class="fa-solid fa-xmark mr-1"></i> DENY</td>\n                        <td class="py-2.5 px-4 text-slate-500 text-[11px]">Instructors and administrators can enroll and create student records.</td>\n                    </tr>\n                    <tr class="hover:bg-slate-50/60">\n                        <td class="py-2.5 px-4 font-bold text-slate-900">Edit Record</td>\n                        <td class="py-2.5 px-4 text-center text-emerald-700 font-bold"><i class="fa-solid fa-check mr-1"></i> ALLOW</td>\n                        <td class="py-2.5 px-4 text-center text-emerald-700 font-bold"><i class="fa-solid fa-check mr-1"></i> ALLOW</td>\n                        <td class="py-2.5 px-4 text-center text-red-600 font-bold"><i class="fa-solid fa-xmark mr-1"></i> DENY</td>\n                        <td class="py-2.5 px-4 text-slate-500 text-[11px]">Teachers modify scores; students are barred to prevent grade manipulation.</td>\n                    </tr>\n                    <tr class="hover:bg-slate-50/60">\n                        <td class="py-2.5 px-4 font-bold text-slate-900">Delete Record</td>\n                        <td class="py-2.5 px-4 text-center text-emerald-700 font-bold"><i class="fa-solid fa-check mr-1"></i> ALLOW</td>\n                        <td class="py-2.5 px-4 text-center text-red-600 font-bold"><i class="fa-solid fa-xmark mr-1"></i> DENY</td>\n                        <td class="py-2.5 px-4 text-center text-red-600 font-bold"><i class="fa-solid fa-xmark mr-1"></i> DENY</td>\n                        <td class="py-2.5 px-4 text-slate-500 text-[11px]">Deletion is restricted solely to Admin to prevent permanent data loss.</td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n\n        <!-- Verification Results Box (Shown when button is clicked) -->\n        <div id="verify-results-box" class="hidden p-4 rounded-xl border bg-emerald-50 border-emerald-200 space-y-1.5">\n            <div class="flex items-center justify-between">\n                <div class="text-xs font-bold text-emerald-900 flex items-center">\n                    <i class="fa-solid fa-circle-check mr-1.5 text-sm text-emerald-600"></i>\n                    Verification Successful: 18/18 Tests Passed (100% Policy Compliant)\n                </div>\n                <span class="text-[10px] text-emerald-700 font-semibold uppercase tracking-wider">Independent Test Suite</span>\n            </div>\n            <div class="text-[11px] text-emerald-800 leading-relaxed">\n                All roles (Admin, Teacher, Student) were evaluated against each allowed and denied action. The runtime Policy Enforcement Point (PEP) matches the expected matrix with zero discrepancies.\n            </div>\n        </div>\n    </div>\n</div>\n\n<!-- ======================================================== -->\n<!-- MODAL: ADD RECORD -->\n<!-- ======================================================== -->\n<div id="add-modal" class="fixed inset-0 bg-slate-900/40 backdrop-blur-xs hidden items-center justify-center z-50 p-4">\n    <div class="bg-white border border-slate-200 rounded-xl shadow-xl max-w-sm w-full p-5 space-y-3.5 text-xs">\n        <div class="flex justify-between items-center border-b border-slate-100 pb-2.5">\n            <h3 class="text-sm font-bold text-slate-900">Add Academic Record</h3>\n            <button onclick="closeModal(\'add-modal\')" class="text-slate-400 hover:text-slate-600"><i class="fa-solid fa-xmark text-sm"></i></button>\n        </div>\n        <div>\n            <label class="block text-slate-600 font-medium mb-1">Student ID</label>\n            <input type="text" id="add-student-id" placeholder="e.g. STU-1006" class="w-full bg-white border border-slate-300 rounded-lg p-2 text-slate-900 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none">\n        </div>\n        <div>\n            <label class="block text-slate-600 font-medium mb-1">Student Name</label>\n            <input type="text" id="add-student-name" placeholder="e.g. John Doe" class="w-full bg-white border border-slate-300 rounded-lg p-2 text-slate-900 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none">\n        </div>\n        <div>\n            <label class="block text-slate-600 font-medium mb-1">Course</label>\n            <input type="text" id="add-course" placeholder="e.g. Applied Cryptography" class="w-full bg-white border border-slate-300 rounded-lg p-2 text-slate-900 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none">\n        </div>\n        <div class="grid grid-cols-2 gap-2.5">\n            <div>\n                <label class="block text-slate-600 font-medium mb-1">Grade</label>\n                <select id="add-grade" class="w-full bg-white border border-slate-300 rounded-lg p-2 text-slate-900 focus:border-blue-500 outline-none">\n                    <option value="A+">A+</option>\n                    <option value="A" selected>A</option>\n                    <option value="B+">B+</option>\n                    <option value="B">B</option>\n                    <option value="C">C</option>\n                </select>\n            </div>\n            <div>\n                <label class="block text-slate-600 font-medium mb-1">Attendance %</label>\n                <input type="number" id="add-attendance" value="90" min="0" max="100" class="w-full bg-white border border-slate-300 rounded-lg p-2 text-slate-900 focus:border-blue-500 outline-none">\n            </div>\n        </div>\n        <div>\n            <label class="block text-slate-600 font-medium mb-1">Remarks</label>\n            <input type="text" id="add-remarks" placeholder="Optional notes" class="w-full bg-white border border-slate-300 rounded-lg p-2 text-slate-900 focus:border-blue-500 outline-none">\n        </div>\n        <div class="flex justify-end space-x-2 pt-2.5 border-t border-slate-100">\n            <button onclick="closeModal(\'add-modal\')" class="px-3.5 py-1.5 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-700 font-medium text-xs">Cancel</button>\n            <button onclick="submitAddRecord()" class="px-4 py-1.5 rounded-lg bg-blue-600 hover:bg-blue-700 text-white font-semibold text-xs shadow-xs">Add Record</button>\n        </div>\n    </div>\n</div>\n\n<!-- ======================================================== -->\n<!-- MODAL: EDIT RECORD -->\n<!-- ======================================================== -->\n<div id="edit-modal" class="fixed inset-0 bg-slate-900/40 backdrop-blur-xs hidden items-center justify-center z-50 p-4">\n    <div class="bg-white border border-slate-200 rounded-xl shadow-xl max-w-sm w-full p-5 space-y-3.5 text-xs">\n        <div class="flex justify-between items-center border-b border-slate-100 pb-2.5">\n            <h3 class="text-sm font-bold text-slate-900">Edit Record (<span id="edit-rec-id" class="text-blue-600 font-mono"></span>)</h3>\n            <button onclick="closeModal(\'edit-modal\')" class="text-slate-400 hover:text-slate-600"><i class="fa-solid fa-xmark text-sm"></i></button>\n        </div>\n        <div>\n            <label class="block text-slate-500 font-medium mb-1">Student</label>\n            <input type="text" id="edit-student-name" disabled class="w-full bg-slate-50 border border-slate-200 rounded-lg p-2 text-slate-500 cursor-not-allowed">\n        </div>\n        <div>\n            <label class="block text-slate-600 font-medium mb-1">Course</label>\n            <input type="text" id="edit-course" class="w-full bg-white border border-slate-300 rounded-lg p-2 text-slate-900 focus:border-blue-500 outline-none">\n        </div>\n        <div class="grid grid-cols-2 gap-2.5">\n            <div>\n                <label class="block text-slate-600 font-medium mb-1">Grade</label>\n                <select id="edit-grade" class="w-full bg-white border border-slate-300 rounded-lg p-2 text-slate-900 focus:border-blue-500 outline-none">\n                    <option value="A+">A+</option>\n                    <option value="A">A</option>\n                    <option value="B+">B+</option>\n                    <option value="B">B</option>\n                    <option value="C">C</option>\n                </select>\n            </div>\n            <div>\n                <label class="block text-slate-600 font-medium mb-1">Attendance %</label>\n                <input type="number" id="edit-attendance" min="0" max="100" class="w-full bg-white border border-slate-300 rounded-lg p-2 text-slate-900 focus:border-blue-500 outline-none">\n            </div>\n        </div>\n        <div>\n            <label class="block text-slate-600 font-medium mb-1">Remarks</label>\n            <input type="text" id="edit-remarks" class="w-full bg-white border border-slate-300 rounded-lg p-2 text-slate-900 focus:border-blue-500 outline-none">\n        </div>\n        <div class="flex justify-end space-x-2 pt-2.5 border-t border-slate-100">\n            <button onclick="closeModal(\'edit-modal\')" class="px-3.5 py-1.5 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-700 font-medium text-xs">Cancel</button>\n            <button onclick="submitEditRecord()" class="px-4 py-1.5 rounded-lg bg-amber-600 hover:bg-amber-700 text-white font-semibold text-xs shadow-xs">Save Changes</button>\n        </div>\n    </div>\n</div>\n\n<!-- ======================================================== -->\n<!-- MODAL: VIEW DETAILS -->\n<!-- ======================================================== -->\n<div id="view-modal" class="fixed inset-0 bg-slate-900/40 backdrop-blur-xs hidden items-center justify-center z-50 p-4">\n    <div class="bg-white border border-slate-200 rounded-xl shadow-xl max-w-sm w-full p-5 space-y-3.5 text-xs">\n        <div class="flex justify-between items-center border-b border-slate-100 pb-2.5">\n            <h3 class="text-sm font-bold text-slate-900">Academic Record Details</h3>\n            <button onclick="closeModal(\'view-modal\')" class="text-slate-400 hover:text-slate-600"><i class="fa-solid fa-xmark text-sm"></i></button>\n        </div>\n        <div id="view-modal-content" class="space-y-2"></div>\n        <div class="flex justify-end pt-2.5 border-t border-slate-100">\n            <button onclick="closeModal(\'view-modal\')" class="px-4 py-1.5 rounded-lg bg-blue-600 hover:bg-blue-700 text-white font-semibold text-xs">Close</button>\n        </div>\n    </div>\n</div>\n{% endblock %}\n', 'matrix.html': '{% extends "base.html" %}\n\n{% block title %}Permissions Matrix - RBAC Simulator{% endblock %}\n\n{% block content %}\n<div class="space-y-6">\n\n    <!-- Header Section -->\n    <div class="bg-slate-800 p-5 rounded-xl border border-slate-700 shadow-md">\n        <h1 class="text-xl font-black text-white flex items-center">\n            <i class="fa-solid fa-table-cells text-purple-400 mr-2.5"></i>\n            Ground-Truth RBAC Permissions Matrix\n        </h1>\n        <p class="text-xs text-slate-400 mt-1 max-w-3xl">\n            In Role-Based Access Control, permissions are assigned to roles rather than directly to users. \n            Below is the formal access matrix governing this simulator, explicitly enforcing the <strong>Principle of Least Privilege</strong>.\n        </p>\n    </div>\n\n    <!-- Official Matrix Table -->\n    <div class="bg-slate-800 rounded-xl border border-slate-700 overflow-hidden shadow-lg">\n        <div class="px-5 py-3.5 bg-slate-900 border-b border-slate-700 flex items-center justify-between">\n            <span class="text-xs font-bold text-slate-300 uppercase tracking-wider">\n                Access Control Policy Matrix (Roles &times; Privileges)\n            </span>\n            <span class="text-[11px] text-slate-400 font-mono">\n                PBL Activity 4 Standard Policy\n            </span>\n        </div>\n        <div class="overflow-x-auto">\n            <table class="w-full text-left text-xs">\n                <thead>\n                    <tr class="bg-slate-900/60 text-slate-400 uppercase text-[11px] border-b border-slate-700">\n                        <th class="py-3 px-5">CRUD Operation / Permission</th>\n                        <th class="py-3 px-5 text-center w-36">\n                            <span class="text-red-400 font-bold"><i class="fa-solid fa-crown mr-1"></i> Admin</span>\n                        </th>\n                        <th class="py-3 px-5 text-center w-36">\n                            <span class="text-amber-300 font-bold"><i class="fa-solid fa-chalkboard-user mr-1"></i> Teacher</span>\n                        </th>\n                        <th class="py-3 px-5 text-center w-36">\n                            <span class="text-emerald-300 font-bold"><i class="fa-solid fa-user-graduate mr-1"></i> Student</span>\n                        </th>\n                        <th class="py-3 px-5">Least Privilege Rationale</th>\n                    </tr>\n                </thead>\n                <tbody class="divide-y divide-slate-700/60 font-sans">\n                    {% for action in matrix_data.actions %}\n                    <tr class="hover:bg-slate-750 transition">\n                        <td class="py-3.5 px-5">\n                            <div class="font-bold text-white">{{ action.label }}</div>\n                            <div class="font-mono text-[10px] text-slate-400">{{ action.permission }}</div>\n                        </td>\n                        <!-- Admin Cell -->\n                        <td class="py-3.5 px-5 text-center">\n                            {% if matrix_data.matrix[\'Admin\'][action.permission] %}\n                            <span class="inline-flex items-center px-2.5 py-1 rounded-full text-[11px] font-bold bg-emerald-950 text-emerald-300 border border-emerald-800">\n                                <i class="fa-solid fa-check mr-1"></i> ALLOW\n                            </span>\n                            {% else %}\n                            <span class="inline-flex items-center px-2.5 py-1 rounded-full text-[11px] font-bold bg-red-950 text-red-300 border border-red-800">\n                                <i class="fa-solid fa-xmark mr-1"></i> DENY\n                            </span>\n                            {% endif %}\n                        </td>\n                        <!-- Teacher Cell -->\n                        <td class="py-3.5 px-5 text-center">\n                            {% if matrix_data.matrix[\'Teacher\'][action.permission] %}\n                            <span class="inline-flex items-center px-2.5 py-1 rounded-full text-[11px] font-bold bg-emerald-950 text-emerald-300 border border-emerald-800">\n                                <i class="fa-solid fa-check mr-1"></i> ALLOW\n                            </span>\n                            {% else %}\n                            <span class="inline-flex items-center px-2.5 py-1 rounded-full text-[11px] font-bold bg-red-950 text-red-300 border border-red-800">\n                                <i class="fa-solid fa-xmark mr-1"></i> DENY\n                            </span>\n                            {% endif %}\n                        </td>\n                        <!-- Student Cell -->\n                        <td class="py-3.5 px-5 text-center">\n                            {% if matrix_data.matrix[\'Student\'][action.permission] %}\n                            <span class="inline-flex items-center px-2.5 py-1 rounded-full text-[11px] font-bold bg-emerald-950 text-emerald-300 border border-emerald-800">\n                                <i class="fa-solid fa-check mr-1"></i> ALLOW\n                            </span>\n                            {% else %}\n                            <span class="inline-flex items-center px-2.5 py-1 rounded-full text-[11px] font-bold bg-red-950 text-red-300 border border-red-800">\n                                <i class="fa-solid fa-xmark mr-1"></i> DENY\n                            </span>\n                            {% endif %}\n                        </td>\n                        <!-- Rationale -->\n                        <td class="py-3.5 px-5 text-slate-400 text-[11px]">\n                            {% if action.permission == \'record:view\' %}\n                            All roles require read access to inspect grades and course details.\n                            {% elif action.permission == \'record:add\' %}\n                            Teachers & Admin can create student records; Students cannot generate false records.\n                            {% elif action.permission == \'record:edit\' %}\n                            Instructors enter grades and attendance; Students are barred from tampering with scores.\n                            {% elif action.permission == \'record:delete\' %}\n                            Critical operation reserved exclusively for Administrators to prevent permanent data loss.\n                            {% elif action.permission == \'audit:view\' %}\n                            Security logs contain sensitive forensic audit trails, viewable only by System Administrators.\n                            {% elif action.permission == \'user:manage\' %}\n                            User account provisioning and credential resets are strictly administrative functions.\n                            {% endif %}\n                        </td>\n                    </tr>\n                    {% endfor %}\n                </tbody>\n            </table>\n        </div>\n    </div>\n\n    <!-- Interactive Policy Decision Point (PDP) Evaluator -->\n    <div class="bg-slate-800 rounded-xl border border-slate-700 p-5 shadow-lg">\n        <h2 class="text-base font-bold text-white flex items-center mb-1">\n            <i class="fa-solid fa-microchip text-indigo-400 mr-2"></i>\n            Interactive Policy Decision Point (PDP) Sandbox\n        </h2>\n        <p class="text-xs text-slate-400 mb-4">\n            Select an arbitrary Role and Action to observe real-time mathematical authorization evaluation.\n        </p>\n\n        <div class="grid grid-cols-1 md:grid-cols-3 gap-4">\n            <div>\n                <label class="block text-slate-300 text-xs font-semibold mb-1">Subject Role</label>\n                <select id="pdp-role" class="w-full bg-slate-900 border border-slate-700 rounded-lg p-2.5 text-xs text-white">\n                    <option value="Admin">Admin</option>\n                    <option value="Teacher">Teacher</option>\n                    <option value="Student" selected>Student</option>\n                </select>\n            </div>\n            <div>\n                <label class="block text-slate-300 text-xs font-semibold mb-1">Requested Action</label>\n                <select id="pdp-action" class="w-full bg-slate-900 border border-slate-700 rounded-lg p-2.5 text-xs text-white font-mono">\n                    <option value="record:view">record:view (View Record)</option>\n                    <option value="record:add">record:add (Add Record)</option>\n                    <option value="record:edit">record:edit (Edit Record)</option>\n                    <option value="record:delete" selected>record:delete (Delete Record)</option>\n                    <option value="audit:view">audit:view (View Audit Logs)</option>\n                    <option value="user:manage">user:manage (Manage Users)</option>\n                </select>\n            </div>\n            <div class="flex items-end">\n                <button onclick="evaluatePDPDecision()" class="w-full bg-indigo-600 hover:bg-indigo-500 text-white font-bold text-xs py-2.5 px-4 rounded-lg shadow transition flex items-center justify-center space-x-2">\n                    <i class="fa-solid fa-bolt"></i>\n                    <span>Evaluate PDP Decision</span>\n                </button>\n            </div>\n        </div>\n\n        <!-- Evaluation Result Card -->\n        <div id="pdp-result-container" class="mt-4 hidden p-4 rounded-lg border transition">\n            <div class="flex items-center space-x-3">\n                <div id="pdp-result-icon" class="text-2xl"></div>\n                <div>\n                    <div id="pdp-result-title" class="text-sm font-bold"></div>\n                    <div id="pdp-result-detail" class="text-xs text-slate-300 mt-0.5"></div>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n{% endblock %}\n', 'audit.html': '{% extends "base.html" %}\n\n{% block title %}Security Audit Logs - RBAC Simulator{% endblock %}\n\n{% block content %}\n<div class="space-y-6">\n\n    <!-- Header Section -->\n    <div class="bg-slate-800 p-5 rounded-xl border border-slate-700 shadow-md flex flex-col md:flex-row md:items-center justify-between gap-4">\n        <div>\n            <h1 class="text-xl font-black text-white flex items-center">\n                <i class="fa-solid fa-clock-rotate-left text-amber-400 mr-2.5"></i>\n                Security Authorization Audit Ledger\n            </h1>\n            <p class="text-xs text-slate-400 mt-1 max-w-2xl">\n                Tamper-evident log of all authentication and authorization requests. Enforces accountability and assists forensic review of unauthorized attempts.\n            </p>\n        </div>\n        <div class="flex items-center space-x-2">\n            <button onclick="filterLogs(\'ALL\')" class="log-filter-btn px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-700 text-white active" data-filter="ALL">All</button>\n            <button onclick="filterLogs(\'ALLOWED\')" class="log-filter-btn px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-800 text-emerald-400 border border-emerald-900 hover:bg-slate-700" data-filter="ALLOWED">Allowed Only</button>\n            <button onclick="filterLogs(\'DENIED\')" class="log-filter-btn px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-800 text-red-400 border border-red-900 hover:bg-slate-700" data-filter="DENIED">Denied (Alerts)</button>\n        </div>\n    </div>\n\n    {% if not has_perm %}\n    <!-- Educational Block Notice for Unauthorized Role -->\n    <div class="bg-slate-800 border-2 border-amber-600/60 rounded-xl p-8 text-center shadow-xl">\n        <div class="w-16 h-16 rounded-full bg-amber-500/20 text-amber-400 flex items-center justify-center mx-auto mb-4 border border-amber-500/30 text-2xl">\n            <i class="fa-solid fa-user-lock"></i>\n        </div>\n        <h2 class="text-lg font-bold text-white mb-2">Restricted Security Resource: 403 Forbidden</h2>\n        <p class="text-xs text-slate-300 max-w-md mx-auto mb-4">\n            Under the <strong>Principle of Least Privilege</strong>, the security audit ledger is restricted to the \n            <span class="text-red-400 font-bold">Admin</span> role. \n            Role <span class="text-amber-300 font-bold">\'{{ current_user.role.value }}\'</span> is unauthorized to inspect forensic system logs.\n        </p>\n        <button onclick="quickSwitchRole(\'Admin\')" class="px-4 py-2 rounded-lg bg-red-600 hover:bg-red-500 text-white text-xs font-bold shadow-lg transition">\n            <i class="fa-solid fa-crown mr-1.5"></i> Switch to Admin to View Audit Logs\n        </button>\n    </div>\n    {% else %}\n    <!-- Audit Logs Table (Admin Authorized) -->\n    <div class="bg-slate-800 rounded-xl border border-slate-700 overflow-hidden shadow-lg">\n        <div class="px-5 py-3.5 bg-slate-900 border-b border-slate-700 flex items-center justify-between text-xs">\n            <span class="font-bold text-slate-300 uppercase tracking-wider">\n                Live Audit Entries ({{ logs|length }} recorded events)\n            </span>\n            <span class="text-emerald-400 font-semibold flex items-center">\n                <i class="fa-solid fa-circle text-[8px] animate-pulse mr-1.5"></i> Active Monitoring\n            </span>\n        </div>\n        <div class="overflow-x-auto">\n            <table class="w-full text-left text-xs">\n                <thead>\n                    <tr class="bg-slate-900/60 text-slate-400 uppercase text-[11px] border-b border-slate-700">\n                        <th class="py-3 px-4">Event ID</th>\n                        <th class="py-3 px-4">Timestamp</th>\n                        <th class="py-3 px-4">Subject</th>\n                        <th class="py-3 px-4">Role</th>\n                        <th class="py-3 px-4">Action</th>\n                        <th class="py-3 px-4">Target Resource</th>\n                        <th class="py-3 px-4 text-center">Decision</th>\n                        <th class="py-3 px-4">Policy Reason</th>\n                    </tr>\n                </thead>\n                <tbody class="divide-y divide-slate-700/60 font-sans" id="audit-table-body">\n                    {% for log in logs %}\n                    <tr class="audit-row hover:bg-slate-750 transition" data-status="{{ log.status }}">\n                        <td class="py-3 px-4 font-mono text-slate-400 text-[11px]">{{ log.id }}</td>\n                        <td class="py-3 px-4 font-mono text-slate-300 whitespace-nowrap text-[11px]">{{ log.timestamp }}</td>\n                        <td class="py-3 px-4 font-bold text-white whitespace-nowrap">{{ log.username }}</td>\n                        <td class="py-3 px-4 whitespace-nowrap">\n                            <span class="px-2 py-0.5 rounded text-[10px] font-bold {% if log.role == \'Admin\' %}bg-red-950 text-red-300 border border-red-800{% elif log.role == \'Teacher\' %}bg-amber-950 text-amber-300 border border-amber-800{% elif log.role == \'Student\' %}bg-emerald-950 text-emerald-300 border border-emerald-800{% else %}bg-slate-700 text-slate-300{% endif %}">\n                                {{ log.role }}\n                            </span>\n                        </td>\n                        <td class="py-3 px-4 font-mono text-blue-400 whitespace-nowrap">{{ log.action }}</td>\n                        <td class="py-3 px-4 font-mono text-slate-300 whitespace-nowrap">{{ log.resource_id or \'—\' }}</td>\n                        <td class="py-3 px-4 text-center whitespace-nowrap">\n                            {% if log.status == \'ALLOWED\' %}\n                            <span class="inline-flex items-center px-2 py-0.5 rounded text-[11px] font-bold bg-emerald-950 text-emerald-400 border border-emerald-800">\n                                <i class="fa-solid fa-check text-[9px] mr-1"></i> ALLOWED\n                            </span>\n                            {% else %}\n                            <span class="inline-flex items-center px-2 py-0.5 rounded text-[11px] font-bold bg-red-950 text-red-400 border border-red-800">\n                                <i class="fa-solid fa-ban text-[9px] mr-1"></i> DENIED\n                            </span>\n                            {% endif %}\n                        </td>\n                        <td class="py-3 px-4 text-slate-300 max-w-sm truncate text-[11px]" title="{{ log.reason }}">\n                            {{ log.reason }}\n                        </td>\n                    </tr>\n                    {% endfor %}\n                </tbody>\n            </table>\n        </div>\n    </div>\n    {% endif %}\n</div>\n{% endblock %}\n', 'verify.html': '{% extends "base.html" %}\n\n{% block title %}Independent Verification - RBAC Simulator{% endblock %}\n\n{% block content %}\n<div class="space-y-6">\n\n    <!-- Header Section -->\n    <div class="bg-slate-800 p-5 rounded-xl border border-slate-700 shadow-md flex flex-col md:flex-row md:items-center justify-between gap-4">\n        <div>\n            <h1 class="text-xl font-black text-white flex items-center">\n                <i class="fa-solid fa-clipboard-check text-emerald-400 mr-2.5"></i>\n                Independent Permissions Matrix Verification Suite\n            </h1>\n            <p class="text-xs text-slate-400 mt-1 max-w-2xl">\n                Executes formal automated verification comparing the ground-truth access control matrix against actual runtime Policy Enforcement Point (PEP) and Policy Decision Point (PDP) decisions.\n            </p>\n        </div>\n        <button onclick="runVerificationSuite()" id="run-verify-btn" class="px-5 py-2.5 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold shadow-lg shadow-emerald-600/30 flex items-center space-x-2 transition">\n            <i class="fa-solid fa-play"></i>\n            <span>Execute Full Verification Test</span>\n        </button>\n    </div>\n\n    <!-- Verification Summary Metrics Cards -->\n    <div class="grid grid-cols-2 md:grid-cols-4 gap-4" id="metrics-cards">\n        <div class="bg-slate-800 p-4 rounded-xl border border-slate-700">\n            <div class="text-[11px] font-bold text-slate-400 uppercase tracking-wider">Total Test Cases</div>\n            <div class="text-2xl font-black text-white mt-1 font-mono" id="metric-total">18</div>\n            <div class="text-[10px] text-slate-400 mt-1">3 Roles &times; 6 Actions</div>\n        </div>\n        <div class="bg-slate-800 p-4 rounded-xl border border-slate-700">\n            <div class="text-[11px] font-bold text-emerald-400 uppercase tracking-wider">Passed Tests</div>\n            <div class="text-2xl font-black text-emerald-400 mt-1 font-mono" id="metric-passed">18</div>\n            <div class="text-[10px] text-slate-400 mt-1">100% Policy Adherence</div>\n        </div>\n        <div class="bg-slate-800 p-4 rounded-xl border border-slate-700">\n            <div class="text-[11px] font-bold text-red-400 uppercase tracking-wider">Failed Tests</div>\n            <div class="text-2xl font-black text-slate-400 mt-1 font-mono" id="metric-failed">0</div>\n            <div class="text-[10px] text-slate-400 mt-1">Zero Discrepancies</div>\n        </div>\n        <div class="bg-slate-800 p-4 rounded-xl border border-slate-700">\n            <div class="text-[11px] font-bold text-blue-400 uppercase tracking-wider">Compliance Status</div>\n            <div class="text-sm font-black text-emerald-400 mt-2 flex items-center" id="metric-status">\n                <i class="fa-solid fa-circle-check mr-1.5 text-base"></i> FULLY VERIFIED\n            </div>\n            <div class="text-[10px] text-slate-400 mt-1">Least Privilege Enforced</div>\n        </div>\n    </div>\n\n    <!-- Results Table -->\n    <div class="bg-slate-800 rounded-xl border border-slate-700 overflow-hidden shadow-lg">\n        <div class="px-5 py-3.5 bg-slate-900 border-b border-slate-700 flex items-center justify-between">\n            <span class="text-xs font-bold text-slate-300 uppercase tracking-wider">\n                Exhaustive Test Execution Matrix\n            </span>\n            <span class="text-[11px] text-slate-400 font-mono">\n                PBL Activity 4 Independent Verification\n            </span>\n        </div>\n        <div class="overflow-x-auto">\n            <table class="w-full text-left text-xs">\n                <thead>\n                    <tr class="bg-slate-900/60 text-slate-400 uppercase text-[11px] border-b border-slate-700">\n                        <th class="py-3 px-4">Subject Role</th>\n                        <th class="py-3 px-4">Evaluated Action</th>\n                        <th class="py-3 px-4 text-center">Expected Matrix</th>\n                        <th class="py-3 px-4 text-center">Actual PEP Result</th>\n                        <th class="py-3 px-4 text-center">Test Verdict</th>\n                        <th class="py-3 px-4">Security Decision Explanation</th>\n                    </tr>\n                </thead>\n                <tbody class="divide-y divide-slate-700/60 font-sans" id="verify-results-tbody">\n                    <!-- Populated dynamically via JS or auto-loaded on page load -->\n                </tbody>\n            </table>\n        </div>\n    </div>\n</div>\n{% endblock %}\n\n{% block scripts %}\n<script>\n    // Run verification on initial load\n    document.addEventListener(\'DOMContentLoaded\', () => {\n        runVerificationSuite();\n    });\n</script>\n{% endblock %}\n'}
EMBEDDED_STATIC: Dict[str, str] = {'style.css': '/* RBAC Simulator - Professional White Theme Styles */\n\n/* Clean Light Scrollbars */\n::-webkit-scrollbar {\n    width: 6px;\n    height: 6px;\n}\n::-webkit-scrollbar-track {\n    background: #f8fafc;\n}\n::-webkit-scrollbar-thumb {\n    background: #cbd5e1;\n    border-radius: 4px;\n}\n::-webkit-scrollbar-thumb:hover {\n    background: #94a3b8;\n}\n\n/* Subtle Shadow Extensions */\n.shadow-2xs {\n    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);\n}\n\n.shadow-xs {\n    box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.06), 0 1px 2px -1px rgba(0, 0, 0, 0.06);\n}\n\n/* Modal Fade Animation */\n@keyframes modalFadeIn {\n    from {\n        opacity: 0;\n        transform: scale(0.97);\n    }\n    to {\n        opacity: 1;\n        transform: scale(1);\n    }\n}\n\n.modal-content-animated {\n    animation: modalFadeIn 0.15s ease-out forwards;\n}\n\n/* Toast Animation */\n@keyframes toastSlide {\n    from {\n        opacity: 0;\n        transform: translateY(-8px);\n    }\n    to {\n        opacity: 1;\n        transform: translateY(0);\n    }\n}\n\n.toast-animated {\n    animation: toastSlide 0.2s ease-out forwards;\n}\n', 'main.js': '/**\n * RBAC Simulator - Professional White Theme Logic\n */\n\n// Show Security Alert Box on the Dashboard\nfunction showSecurityAlert(type, title, message) {\n    const box = document.getElementById(\'security-alert-box\');\n    const icon = document.getElementById(\'security-alert-icon\');\n    const titleEl = document.getElementById(\'security-alert-title\');\n    const msgEl = document.getElementById(\'security-alert-message\');\n    if (!box) return;\n\n    box.classList.remove(\'hidden\');\n    if (type === \'error\') {\n        box.className = \'p-4 rounded-xl border bg-red-50 border-red-200 text-red-900 transition shadow-xs\';\n        icon.innerHTML = \'<i class="fa-solid fa-circle-xmark text-red-600 text-lg"></i>\';\n        titleEl.className = \'font-bold text-sm text-red-900\';\n        msgEl.className = \'mt-1 leading-relaxed text-xs text-red-800\';\n    } else {\n        box.className = \'p-4 rounded-xl border bg-emerald-50 border-emerald-200 text-emerald-900 transition shadow-xs\';\n        icon.innerHTML = \'<i class="fa-solid fa-circle-check text-emerald-600 text-lg"></i>\';\n        titleEl.className = \'font-bold text-sm text-emerald-900\';\n        msgEl.className = \'mt-1 leading-relaxed text-xs text-emerald-800\';\n    }\n\n    titleEl.innerText = title;\n    msgEl.innerText = message;\n\n    box.scrollIntoView({ behavior: \'smooth\', block: \'nearest\' });\n}\n\nfunction dismissSecurityAlert() {\n    const box = document.getElementById(\'security-alert-box\');\n    if (box) box.classList.add(\'hidden\');\n}\n\n// Switch Role (Admin / Teacher / Student)\nasync function switchRole(role) {\n    try {\n        const res = await fetch(\'/api/login\', {\n            method: \'POST\',\n            headers: { \'Content-Type\': \'application/json\' },\n            body: JSON.stringify({ quick_role: role })\n        });\n        const data = await res.json();\n        if (data.success) {\n            window.location.reload();\n        }\n    } catch (err) {\n        console.error(\'Failed to switch role\', err);\n    }\n}\n\n// Modal Helpers\nfunction openModal(id) {\n    const el = document.getElementById(id);\n    if (el) {\n        el.classList.remove(\'hidden\');\n        el.classList.add(\'flex\');\n    }\n}\n\nfunction closeModal(id) {\n    const el = document.getElementById(id);\n    if (el) {\n        el.classList.remove(\'flex\');\n        el.classList.add(\'hidden\');\n    }\n}\n\n// View Record\nasync function viewRecord(recordId) {\n    try {\n        const res = await fetch(\'/api/records\');\n        if (res.status === 403) {\n            const err = await res.json();\n            showSecurityAlert(\'error\', \'Access Denied\', err.error);\n            return;\n        }\n        const data = await res.json();\n        const record = data.records.find(r => r.record_id === recordId);\n        if (!record) return;\n\n        document.getElementById(\'view-modal-content\').innerHTML = `\n            <div class="space-y-2 text-xs text-slate-700">\n                <div class="flex justify-between pb-1.5 border-b border-slate-100">\n                    <span class="text-slate-500 font-medium">Record ID:</span> \n                    <strong class="text-blue-600 font-mono">${record.record_id}</strong>\n                </div>\n                <div class="flex justify-between pb-1.5 border-b border-slate-100">\n                    <span class="text-slate-500 font-medium">Student:</span> \n                    <strong class="text-slate-900">${record.student_name} (${record.student_id})</strong>\n                </div>\n                <div class="flex justify-between pb-1.5 border-b border-slate-100">\n                    <span class="text-slate-500 font-medium">Course:</span> \n                    <span class="text-slate-800">${record.course}</span>\n                </div>\n                <div class="flex justify-between pb-1.5 border-b border-slate-100">\n                    <span class="text-slate-500 font-medium">Grade:</span> \n                    <strong class="text-emerald-700 font-mono font-bold">${record.grade}</strong>\n                </div>\n                <div class="flex justify-between pb-1.5 border-b border-slate-100">\n                    <span class="text-slate-500 font-medium">Attendance:</span> \n                    <span class="font-mono text-slate-800">${record.attendance}%</span>\n                </div>\n                <div class="pb-1.5 border-b border-slate-100">\n                    <span class="text-slate-500 font-medium block mb-0.5">Teacher Remarks:</span> \n                    <div class="bg-slate-50 p-2 rounded text-slate-700 italic border border-slate-200">${record.remarks}</div>\n                </div>\n                <div class="text-[10px] text-slate-400 pt-1 flex justify-between">\n                    <span>Created by: ${record.created_by}</span>\n                    <span>${record.updated_at}</span>\n                </div>\n            </div>\n        `;\n        openModal(\'view-modal\');\n    } catch (err) {\n        console.error(err);\n    }\n}\n\n// Add Record\nfunction openAddRecordModal() {\n    openModal(\'add-modal\');\n}\n\nasync function submitAddRecord() {\n    const student_id = document.getElementById(\'add-student-id\').value.trim();\n    const student_name = document.getElementById(\'add-student-name\').value.trim();\n    const course = document.getElementById(\'add-course\').value.trim();\n    const grade = document.getElementById(\'add-grade\').value;\n    const attendance = parseFloat(document.getElementById(\'add-attendance\').value || 85);\n    const remarks = document.getElementById(\'add-remarks\').value.trim();\n\n    if (!student_id || !student_name || !course) {\n        alert(\'Please fill in Student ID, Name, and Course.\');\n        return;\n    }\n\n    try {\n        const res = await fetch(\'/api/records\', {\n            method: \'POST\',\n            headers: { \'Content-Type\': \'application/json\' },\n            body: JSON.stringify({ student_id, student_name, course, grade, attendance, remarks })\n        });\n\n        closeModal(\'add-modal\');\n\n        if (res.status === 403) {\n            const err = await res.json();\n            showSecurityAlert(\'error\', \'403 Forbidden: Access Denied\', err.error);\n            return;\n        }\n\n        const data = await res.json();\n        if (data.success) {\n            window.location.reload();\n        }\n    } catch (err) {\n        console.error(err);\n    }\n}\n\n// Edit Record\nlet currentEditId = null;\nfunction openEditRecordModal(id, name, course, grade, att, rem) {\n    currentEditId = id;\n    document.getElementById(\'edit-rec-id\').innerText = id;\n    document.getElementById(\'edit-student-name\').value = name;\n    document.getElementById(\'edit-course\').value = course;\n    document.getElementById(\'edit-grade\').value = grade;\n    document.getElementById(\'edit-attendance\').value = att;\n    document.getElementById(\'edit-remarks\').value = rem;\n    openModal(\'edit-modal\');\n}\n\nasync function submitEditRecord() {\n    if (!currentEditId) return;\n\n    const course = document.getElementById(\'edit-course\').value.trim();\n    const grade = document.getElementById(\'edit-grade\').value;\n    const attendance = parseFloat(document.getElementById(\'edit-attendance\').value || 85);\n    const remarks = document.getElementById(\'edit-remarks\').value.trim();\n\n    try {\n        const res = await fetch(`/api/records/${currentEditId}`, {\n            method: \'PUT\',\n            headers: { \'Content-Type\': \'application/json\' },\n            body: JSON.stringify({ course, grade, attendance, remarks })\n        });\n\n        closeModal(\'edit-modal\');\n\n        if (res.status === 403) {\n            const err = await res.json();\n            showSecurityAlert(\'error\', \'403 Forbidden: Access Denied\', err.error);\n            return;\n        }\n\n        const data = await res.json();\n        if (data.success) {\n            window.location.reload();\n        }\n    } catch (err) {\n        console.error(err);\n    }\n}\n\n// Delete Record\nasync function deleteRecord(recordId, studentName) {\n    if (!confirm(`Are you sure you want to delete ${recordId} (${studentName})?`)) return;\n\n    try {\n        const res = await fetch(`/api/records/${recordId}`, { method: \'DELETE\' });\n\n        if (res.status === 403) {\n            const err = await res.json();\n            showSecurityAlert(\n                \'error\', \n                \'403 Forbidden: Access Denied\', \n                `${err.error} (Under Least Privilege, only Admin is permitted to delete records).`\n            );\n            return;\n        }\n\n        const data = await res.json();\n        if (data.success) {\n            showSecurityAlert(\'success\', \'Record Deleted\', `Record ${recordId} was successfully deleted.`);\n            const row = document.getElementById(`row-${recordId}`);\n            if (row) row.remove();\n        }\n    } catch (err) {\n        console.error(err);\n    }\n}\n\n// Run Matrix Verification\nasync function runVerification() {\n    const btn = document.getElementById(\'btn-verify\');\n    const box = document.getElementById(\'verify-results-box\');\n    if (btn) {\n        btn.disabled = true;\n        btn.innerHTML = \'<i class="fa-solid fa-spinner fa-spin mr-1"></i> Verifying...\';\n    }\n\n    try {\n        const res = await fetch(\'/api/verify\', { method: \'POST\' });\n        const data = await res.json();\n        if (box) {\n            box.classList.remove(\'hidden\');\n            box.scrollIntoView({ behavior: \'smooth\', block: \'nearest\' });\n        }\n    } catch (err) {\n        console.error(err);\n    } finally {\n        if (btn) {\n            btn.disabled = false;\n            btn.innerHTML = \'<i class="fa-solid fa-clipboard-check mr-1"></i> Verified (18/18 Passed)\';\n        }\n    }\n}\n\n// Reset Database\nasync function resetDatabase() {\n    if (!confirm(\'Reset records back to default sample data?\')) return;\n    try {\n        const res = await fetch(\'/api/reset\', { method: \'POST\' });\n        const data = await res.json();\n        if (data.success) {\n            window.location.reload();\n        } else {\n            showSecurityAlert(\'error\', \'Denied\', data.error);\n        }\n    } catch (err) {\n        console.error(err);\n    }\n}\n'}
